import ezdxf, sys
def r(v): return tuple(round(x,3) for x in (v.x, v.y))
for n in sys.argv[1:]:
    d = ezdxf.readfile(r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\13-11-2026\%s.dxf' % n)
    m = d.modelspace()
    print('=====', n, len(m), 'blocks', [b.name for b in d.blocks if not b.name.startswith('*')])
    for e in m:
        t = e.dxftype()
        if t == 'LINE': print(t, e.dxf.layer, r(e.dxf.start), r(e.dxf.end))
        elif t == 'ARC': print(t, e.dxf.layer, r(e.dxf.center), round(e.dxf.radius,3), round(e.dxf.start_angle,2), round(e.dxf.end_angle,2))
        elif t == 'CIRCLE': print(t, e.dxf.layer, r(e.dxf.center), round(e.dxf.radius,3))
        elif t == 'INSERT': print(t, e.dxf.layer, e.dxf.name, r(e.dxf.insert))
        else: print(t, e.dxf.layer)

